export interface CollectionFilters {
  tab: string;
  categories: string[];
  sizes: string[];
  maxPrice: number;
  inStock: boolean;
  query: string;
  sort: string;
}
export function defaultFilters(): CollectionFilters {
  return {
    tab: "all",
    categories: [],
    sizes: [],
    maxPrice: 100,
    inStock: false,
    query: "",
    sort: "featured",
  };
}
export function filterProducts(
  items: readonly CollectionProduct[],
  filters: CollectionFilters,
): CollectionProduct[] {
  const query = filters.query.trim().toLocaleLowerCase("en-GB");
  const result = items.filter(
    (product) =>
      (filters.tab === "all" || product.category === filters.tab) &&
      (!filters.categories.length ||
        filters.categories.includes(product.category)) &&
      (!filters.sizes.length ||
        filters.sizes.some((size) => product.sizes.includes(size))) &&
      product.price <= filters.maxPrice &&
      (!filters.inStock || product.inStock) &&
      `${product.name} ${product.category}`
        .toLocaleLowerCase("en-GB")
        .includes(query),
  );
  if (filters.sort === "price-low") result.sort((a, b) => a.price - b.price);
  if (filters.sort === "price-high") result.sort((a, b) => b.price - a.price);
  if (filters.sort === "name")
    result.sort((a, b) => a.name.localeCompare(b.name, "en-GB"));
  return result;
}

export interface ActiveCollectionFilter {
  id: string;
  kind: "tab" | "category" | "size" | "price" | "stock" | "query";
  value?: string;
  label: string;
}
/** Sorting changes order, not membership, so it is not an active filter. */
export function activeCollectionFilters(
  filters: CollectionFilters,
): ActiveCollectionFilter[] {
  const active: ActiveCollectionFilter[] = [];
  if (filters.tab !== "all")
    active.push({
      id: "tab",
      kind: "tab",
      label: `Collection: ${filters.tab}`,
    });
  for (const category of filters.categories)
    active.push({
      id: `category:${category}`,
      kind: "category",
      value: category,
      label: `Category: ${category}`,
    });
  for (const size of filters.sizes)
    active.push({
      id: `size:${size}`,
      kind: "size",
      value: size,
      label: `Size: ${size}`,
    });
  if (filters.maxPrice < defaultFilters().maxPrice)
    active.push({
      id: "price",
      kind: "price",
      label: `Up to ${new Intl.NumberFormat("en-GB", { style: "currency", currency: "GBP" }).format(filters.maxPrice)}`,
    });
  if (filters.inStock)
    active.push({ id: "stock", kind: "stock", label: "In stock only" });
  if (filters.query.trim())
    active.push({
      id: "query",
      kind: "query",
      label: `Search: ${filters.query.trim()}`,
    });
  return active;
}
/** Remove exactly one constraint; preserve the remaining filters and sort order. */
export function removeCollectionFilter(
  filters: CollectionFilters,
  filter: ActiveCollectionFilter,
): CollectionFilters {
  const next = {
    ...filters,
    categories: [...filters.categories],
    sizes: [...filters.sizes],
  };
  switch (filter.kind) {
    case "tab":
      next.tab = "all";
      break;
    case "category":
      next.categories = next.categories.filter(
        (value) => value !== filter.value,
      );
      break;
    case "size":
      next.sizes = next.sizes.filter((value) => value !== filter.value);
      break;
    case "price":
      next.maxPrice = defaultFilters().maxPrice;
      break;
    case "stock":
      next.inStock = false;
      break;
    case "query":
      next.query = "";
      break;
  }
  return next;
}
